<?php declare(strict_types=1);require_once __DIR__.'/../session-security.php';session_start();sessionSecurityEnforce();require_once __DIR__.'/../mapa/banco.php';require_once __DIR__.'/../auth.php';$pdo=db();authInit($pdo);if(!authLogged()){header('Location: ../login.php');exit;}authRequirePermission($pdo,'app.professor',false);if(!authProfessorId()){http_response_code(403);die('Seu login de Professor ainda não está vinculado a um professor cadastrado no Mapa. Peça ao Diretor Master para fazer o vínculo.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Professor • Liceu Brasil</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;background:#f4f8fc;color:#17324d}.top{background:#075aa8;color:#fff;padding:16px 22px;display:flex;justify-content:space-between}.top a{color:#fff}.wrap{max-width:1000px;margin:auto;padding:24px}.card{background:#fff;border:1px solid #dce6f0;border-radius:14px;padding:16px;margin-bottom:12px}.turma{cursor:pointer}.turma:hover{border-color:#7db6e6}.muted{color:#718096;font-size:12px}.btn{border:0;border-radius:8px;padding:9px 12px;font-weight:800;cursor:pointer;background:#075aa8;color:#fff}.aluno{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-top:1px solid #edf1f5}.pres{display:flex;gap:8px}.pres button{background:#eef3f8;color:#40556a}.pres button.on{background:#075aa8;color:#fff}.back{margin-bottom:12px}.hidden{display:none}input{padding:9px;border:1px solid #ccd8e5;border-radius:8px}@media(max-width:600px){.aluno{align-items:flex-start;gap:8px;flex-direction:column}.pres{width:100%}.pres button{flex:1}}</style></head><body><div class="top"><b>Painel do Professor</b><a href="../index.php">← Central de Apps</a></div><main class="wrap"><div id="lista"><h2>Minhas turmas</h2><p class="muted">Somente turmas vinculadas ao seu cadastro de professor.</p><div id="turmas">Carregando...</div></div><div id="chamada" class="hidden"><button class="btn back" onclick="voltar()">← Minhas turmas</button><div class="card"><h2 id="titulo"></h2><div class="muted" id="meta"></div><div style="margin-top:12px"><label>Data da aula: <input type="date" id="data"></label></div></div><div class="card"><h3>Chamada</h3><div id="alunos"></div><button class="btn" style="margin-top:14px" onclick="salvar()">Salvar chamada</button></div></div></main><script>let atual=null,lista=[];const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));async function api(url,opt){const r=await fetch('api.php?'+url,opt);const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Erro');return j}async function load(){try{const j=await api('action=turmas');turmas.innerHTML=(j.turmas||[]).map(t=>`<div class="card turma" onclick="abrir(${t.agendaId})"><b>${esc(t.turma)}</b><div class="muted">${esc(t.dia)} • ${esc(t.horario)} • ${esc(t.sala||'Sem sala')} • ${t.alunos} aluno(s)</div></div>`).join('')||'<div class="card">Nenhuma turma vinculada.</div>'}catch(e){turmas.textContent=e.message}}async function abrir(id){try{const j=await api('action=chamada&agendaId='+id+'&data='+dataHoje());atual=j;lista=j.alunos||[];titulo.textContent=j.turma;meta.textContent=`${j.dia} • ${j.horario} • ${j.sala||'Sem sala'}`;data.value=dataHoje();render();document.getElementById('lista').classList.add('hidden');chamada.classList.remove('hidden')}catch(e){alert(e.message)}}function dataHoje(){return new Date().toLocaleDateString('sv-SE')}function render(){alunos.innerHTML=lista.map((a,i)=>`<div class="aluno"><div><b>${esc(a.nome)}</b><div class="muted">${esc(a.status||'Ativo')}</div></div><div class="pres"><button class="btn ${a.presente!==0?'on':''}" onclick="setP(${i},1)">Presente</button><button class="btn ${a.presente===0?'on':''}" onclick="setP(${i},0)">Falta</button></div></div>`).join('')||'<div class="muted">Nenhum aluno ativo nesta turma.</div>'}function setP(i,v){lista[i].presente=v;render()}data?.addEventListener?.('change',async()=>{if(atual)await abrirData()});async function abrirData(){const j=await api('action=chamada&agendaId='+atual.agendaId+'&data='+data.value);atual=j;lista=j.alunos||[];render()}async function salvar(){try{await api('action=salvar_chamada',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({agendaId:atual.agendaId,data:data.value,presencas:lista.map(a=>({alunoId:a.id,presente:a.presente!==0}))})});alert('Chamada salva com sucesso.')}catch(e){alert(e.message)}}function voltar(){chamada.classList.add('hidden');document.getElementById('lista').classList.remove('hidden')}load();</script></body></html>
